<?php
$staff=in_array(role(),['admin','pengurus'],true);$edit=null;if($staff&&get('edit')){$s=db()->prepare('SELECT * FROM kegiatan WHERE id=?');$s->execute([(int)get('edit')]);$edit=$s->fetch();}
$rows=db()->query($staff?'SELECT k.*,u.nama pembuat FROM kegiatan k LEFT JOIN users u ON u.id=k.dibuat_oleh ORDER BY k.mulai_pada DESC LIMIT 150':"SELECT k.*,u.nama pembuat FROM kegiatan k LEFT JOIN users u ON u.id=k.dibuat_oleh WHERE k.status<>'dibatalkan' ORDER BY k.mulai_pada DESC LIMIT 150")->fetchAll();
?>
<div class="page-heading"><div><h1>Kegiatan RT</h1><p><?= $staff?'Atur jadwal kegiatan dan informasi pelaksanaan lingkungan.':'Lihat agenda dan kegiatan di lingkungan RT.' ?></p></div><?php if($staff): ?><a class="btn btn-army" href="<?= e(url('kegiatan',['new'=>1])) ?>"><i class="bi bi-calendar-plus me-2"></i>Tambah Kegiatan</a><?php endif; ?></div>
<?php if($staff&&(get('new')||$edit)): ?><section class="panel-card mb-4"><div class="panel-card-header"><h2 class="panel-title"><?= $edit?'Edit Kegiatan':'Kegiatan Baru' ?></h2><a class="text-link" href="<?= e(url('kegiatan')) ?>">Tutup</a></div><div class="panel-card-body"><form method="post" action="index.php" class="row g-3" data-disable-submit><?= csrf_field() ?><input type="hidden" name="action" value="save_kegiatan"><input type="hidden" name="return_page" value="kegiatan"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="col-md-8"><label class="form-label">Nama kegiatan</label><input class="form-control" name="nama_kegiatan" value="<?= e($edit['nama_kegiatan']??'') ?>" required></div><div class="col-md-4"><label class="form-label">Penanggung jawab</label><input class="form-control" name="penanggung_jawab" value="<?= e($edit['penanggung_jawab']??'') ?>"></div><div class="col-md-6"><label class="form-label">Mulai pada</label><input class="form-control" type="datetime-local" name="mulai_pada" value="<?= e(isset($edit['mulai_pada'])?date('Y-m-d\TH:i',strtotime($edit['mulai_pada'])):'') ?>" required></div><div class="col-md-6"><label class="form-label">Selesai pada (opsional)</label><input class="form-control" type="datetime-local" name="selesai_pada" value="<?= e(isset($edit['selesai_pada'])&&$edit['selesai_pada']?date('Y-m-d\TH:i',strtotime($edit['selesai_pada'])):'') ?>"></div><div class="col-12"><label class="form-label">Lokasi</label><input class="form-control" name="lokasi" value="<?= e($edit['lokasi']??'') ?>" required></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea class="form-control" name="deskripsi" rows="4"><?= e($edit['deskripsi']??'') ?></textarea></div><div class="col-12 d-flex justify-content-end gap-2"><a class="btn btn-outline-secondary" href="<?= e(url('kegiatan')) ?>">Batal</a><button class="btn btn-army">Simpan Kegiatan</button></div></form></div></section><?php endif; ?>
<div class="row g-3"><?php if(!$rows): ?><div class="col-12"><div class="panel-card empty-state"><i class="bi bi-calendar2-x"></i><strong>Belum ada kegiatan</strong><span>Agenda lingkungan yang dibuat pengurus akan muncul di sini.</span></div></div><?php else: foreach($rows as $k): ?><div class="col-md-6 col-xl-4"><article class="panel-card h-100 p-4"><div class="d-flex align-items-start justify-content-between mb-3"><div class="activity-date"><strong><?= e(date('d',strtotime($k['mulai_pada']))) ?></strong><?= e(date('M',strtotime($k['mulai_pada']))) ?></div><?= status_badge($k['status']) ?></div><h2 class="h5 fw-bold"><?= e($k['nama_kegiatan']) ?></h2><p class="text-muted-2 small mb-3"><?= e($k['deskripsi']??'') ?></p><div class="small text-muted-2 mb-2"><i class="bi bi-clock me-2"></i><?= e(format_datetime($k['mulai_pada'])) ?></div><div class="small text-muted-2 mb-3"><i class="bi bi-geo-alt me-2"></i><?= e($k['lokasi']) ?></div><div class="border-top pt-3 d-flex justify-content-between align-items-center"><small class="text-muted-2">PJ: <?= e($k['penanggung_jawab']??'-') ?></small><?php if($staff): ?><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-army" href="<?= e(url('kegiatan',['edit'=>$k['id']])) ?>">Edit</a><?php if($k['status']!=='dibatalkan'&&$k['status']!=='selesai'): ?><form method="post" action="index.php"><?= csrf_field() ?><input type="hidden" name="action" value="delete_kegiatan"><input type="hidden" name="return_page" value="kegiatan"><input type="hidden" name="id" value="<?= $k['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Batalkan kegiatan ini?">Batalkan</button></form><?php endif; ?></div><?php endif; ?></div></article></div><?php endforeach; endif; ?></div>
